import { encodeBase64Url } from "@kitty/signing";

/**
 * Secret tokens generated by `apps/api` (docs/09-data-model.md §2).
 *
 * `member_token` unlocks the no-login member portal, so it is 32 random bytes
 * of CSPRNG output encoded base64url — never derived from the member id. It is
 * returned to the organizer (who shares the link) and to nobody else.
 */
export function newMemberToken(): string {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);

  return encodeBase64Url(bytes);
}
